pragma solidity >=0.8.0;

contract ArrayEventProbe {
    uint256[] public vals;
    string[] public items;

    event Arr(uint256[] vals, string[] items);
    event Tup(uint256 a, string b, bytes c);

    function push(uint256 v, string memory i) public returns (uint256) {
        vals.push(v);
        items.push(i);
        return vals.length;
    }

    function emitArr() public {
        emit Arr(vals, items);
    }

    function emitTup(string memory sv, bytes memory d) public {
        emit Tup(42, sv, d);
    }
}
